#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
static bool ok(const vector<int>& h,int cut,int need){ int total=0; for(int x:h){ if(x>cut) total+=x-cut; if(total>=need) return true; } return total>=need; }
int main(){ int n, need; if(!(cin>>n>>need)) return 0; vector<int> h(n); int hi=0; for(int i=0;i<n;i++){ cin>>h[i]; hi=max(hi,h[i]); } int lo=0, ans=0; while(lo<=hi){ int mid=lo+(hi-lo)/2; if(ok(h,mid,need)){ ans=mid; lo=mid+1; } else hi=mid-1; } cout<<ans<<'\n'; return 0; }
